    throw new Error(`Unknown tool: ${name}`);
  }

  // Strict argument validation (mirrors the strict input schema).
  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
    throw new Error('arguments must be an object');
  }
  const allowed = new Set(FILE_METADATA_TOOL.inputSchema.properties ? Object.keys(FILE_METADATA_TOOL.inputSchema.properties) : []);
  for (const key of Object.keys(args)) {
    if (!allowed.has(key)) {
      throw new Error(`Unknown argument: ${key}`);
    }
  }
  const { path: rel } = args;
  if (typeof rel !== 'string' || rel.length === 0) {
    throw new Error('path is required');
  }

  // Resolve the requested path and ensure it stays inside DATA_DIR.
  const fullPath = path.resolve(DATA_DIR, rel);
  const relToData = path.relative(DATA_DIR, fullPath);
  if (relToData === '' || relToData.startsWith('..') || path.isAbsolute(rel)) {
    throw new Error('path must stay within the data directory');
  }

  let stat;
  try {
    stat = await fs.stat(fullPath);
  } catch (error) {
    throw new Error(`File not found: ${rel}`);
  }
  if (!stat.isFile()) {
    throw new Error(`Not a file: ${rel}`);
  }

  // Use forward slashes for a stable, portable relative path.
  const relPath = relToData.split(path.sep).join('/');
  const ext = path.extname(rel).toLowerCase();
  const text =
    `path: ${relPath}\n` +
    `size: ${stat.size} bytes\n` +
    `extension: ${ext}`;

  return {
    content: [{ type: 'text', text }],
  };
}
